result.output:
897	      toggleReadOnly: () => sel && this.update(selId, { readOnly: !sel.readOnly }),
898	      addOption: () => sel && this.update(selId, { options: [...(sel.options || []), "New option"] }),
899	      addRule: () => this.setState(s => {
900	        const cur = s.rulesByQ[selId] || [];
901	        const pool = s.sections.flatMap(x => x.children).filter(c => c.id !== selId);
902	        const pick = pool[cur.length % pool.length] || { num: "1.1", title: "Question" };
903	        return {
904	          tab: "logic",
905	          rulesByQ: { ...s.rulesByQ, [selId]: [...cur, { id: "r" + Date.now(), qnum: pick.num, question: pick.title, operator: "is answered", value: "—" }] }
906	        };
907	      }),
908	      removeRule: e => {
909	        const id = e.currentTarget.dataset.rid;
910	        this.setState(s => ({ rulesByQ: { ...s.rulesByQ, [selId]: (s.rulesByQ[selId] || []).filter(r => r.id !== id) } }));
911	      },
912	      toggleCapture: e => { const k = e.currentTarget.dataset.cap; this.setState(s => ({ captures: { ...s.captures, [k]: !s.captures[k] } })); },
913	      addQuestion: e => {
914	        if (e && e.stopPropagation) e.stopPropagation();
915	        const target = e && e.currentTarget.dataset.sec;
916	        this.setState(s => {
917	          const at = this.locate(selId);
918	          let idx = s.sections.findIndex(x => x.id === (target || selId));
919	          if (idx < 0) idx = at ? at.i : s.sections.length - 1;
920	          const secs = s.sections.map(x => ({ ...x, children: [...x.children] }));
921	          const fresh = { id: "new" + Date.now(), num: "", title: "Untitled question", type: "string", required: false, placeholder: "Type an answer", help: "" };
922	          secs[idx].children.push(fresh);
923	          this.pendingScroll = true;
924	          return { sections: this.renumber(secs), selId: fresh.id, tab: "content" };
925	        });
926	      },
927	      addSection: () => this.setState(s => {
928	        const fresh = { id: "sec" + Date.now(), num: "", title: "New section", children: [] };
929	        this.pendingScroll = true;
930	        return { sections: this.renumber([...s.sections, fresh]), selId: fresh.id };
931	      }),
932	      editSectionTitle: e => this.update(selId, { title: e.target.value })
933	    };
934	  }
935	}
936	</script>
