46	function RendererBody({ className }: { className?: string }) {
47	  const { t } = useTranslation();
48	  const { questionnaire } = useRenderer();
49	  const [activeGroupIndex, setActiveGroupIndex] = useAtom(activeGroupIndexAtom);
50	  // Pagination operates over the enable_when-visible top-level questions
51	  // only — a hidden question would otherwise render as a blank page.
52	  const visibleIndices = useVisibleTopLevelIndices();
53	  // Tree-wide hidden set (any depth) for the nav, so hidden sub-questions
54	  // don't keep dead rows.
55	  const hiddenIds = useHiddenQuestionIds();
56	  const [navOpen, setNavOpen] = useState(true);
57	
58	  if (questionnaire.questions.length === 0) {
59	    return (
60	      <div
61	        className={cn(
62	          "rounded-lg bg-white p-8 text-center text-sm text-gray-500",
63	          className,
64	        )}
65	      >
66	        {t("no_questions_added_yet")}
67	      </div>
68	    );
69	  }
70	
71	  const header = (
72	    <div className="space-y-1 pb-4">
73	      <h2 className="text-base font-semibold text-gray-900">
74	        {questionnaire.title}
75	      </h2>
76	      {questionnaire.description && (
77	        <p className="text-sm text-gray-500">{questionnaire.description}</p>
78	      )}
79	    </div>
80	  );
81	
82	  // Every top-level question hidden by enable_when: explain the empty form
83	  // instead of a blank strip with dead pagination buttons.
84	  if (visibleIndices.length === 0) {
85	    return (
86	      <div className={cn("flex gap-6", className)}>
87	        <div className="min-w-0 flex-1 rounded-lg bg-white px-6 py-4 lg:px-12">
88	          <div className="mx-auto w-full max-w-3xl">
89	            {header}
90	            <div className="p-8 text-center text-sm text-gray-500">
91	              {t("no_visible_questions")}
92	            </div>
93	          </div>
94	        </div>
95	      </div>
96	    );
97	  }
98	
99	  // Snap to the first visible question when the stored index points at a
100	  // hidden (or out-of-range) one — e.g. its condition stopped matching.
101	  const activeIndex = visibleIndices.includes(activeGroupIndex)
102	    ? activeGroupIndex
103	    : (visibleIndices[0] ?? 0);
104	  const activeQuestion =
105	    questionnaire.questions[activeIndex] ?? questionnaire.questions[0];
106	
107	  return (
108	    <div className={cn("flex gap-6", className)}>
109	      {/* A nav with a single entry has nothing to navigate between — and
110	          would otherwise show the active question's title a second time
111	          right next to its own field label. */}
112	      {questionnaire.questions.length > 1 &&
113	        (navOpen ? (
114	          <div className="hidden w-64 shrink-0 lg:block">
115	            <div className="flex items-center justify-between gap-2 px-3 py-2">
116	              <h3 className="min-w-0 truncate text-sm font-semibold text-gray-900">
117	                {questionnaire.title}
118	              </h3>
119	              <Button
120	                type="button"
121	                variant="ghost"
122	                size="icon"
123	                className="shrink-0"
124	                onClick={() => setNavOpen(false)}
125	                aria-label={t("collapse_sidebar")}
126	              >
127	                <PanelLeft className="size-5" />
128	              </Button>
129	            </div>
130	            <QuestionTreeNav
131	              questions={questionnaire.questions}
132	              activeId={activeQuestion.id}
133	              hiddenIds={hiddenIds}
134	              onSelect={(questionId) =>
135	                setActiveGroupIndex(
136	                  findTopLevelIndex(questionnaire.questions, questionId),
137	                )
138	              }
139	            />
140	          </div>
141	        ) : (
142	          // Collapsed rail: just the expand toggle, content re-centres.
143	          <div className="hidden w-10 shrink-0 lg:block">
144	            <Button
145	              type="button"
146	              variant="ghost"
147	              size="icon"
148	              onClick={() => setNavOpen(true)}
149	              aria-label={t("expand_sidebar")}
150	            >
151	              <PanelLeft className="size-5" />
152	            </Button>
153	          </div>
154	        ))}
155	      <div className="min-w-0 flex-1 rounded-lg bg-white px-6 py-4 lg:px-12">
156	        <div className="mx-auto w-full max-w-3xl">
157	          {header}
158	          <div className="pb-4">
159	            <QuestionField
160	              question={activeQuestion}
161	              depth={0}
162	              number={`${activeIndex + 1}.`}
163	            />
164	          </div>
165	          <RendererFooter />
166	        </div>
167	      </div>
168	    </div>
169	  );
170	}
