1	/**
2	 * Renderer state scope: the renderer currently ships preview/read-only modes
3	 * only (`RendererMode`), so `responsesAtom` is local working state with no
4	 * submission consumer yet, and `errorsAtom` has readers (QuestionField,
5	 * StructuredQuestionSlot) but no writer — validation errors cannot appear
6	 * until the fill/submit path lands, which will add the writer, a `"fill"`
7	 * mode and a real `clearError`. Neither is broken; they are the seams the
8	 * submit flow plugs into.
9	 */
10	import { atom, useAtom, useAtomValue } from "jotai";
11	import { useMemo } from "react";
12	
13	import { QuestionValidationError } from "@/types/questionnaire/batch";
14	import {
15	  QuestionnaireResponse,
16	  ResponseValue,
17	} from "@/types/questionnaire/form";
18	import { EnableWhen, Question } from "@/types/questionnaire/question";
19	import { QuestionnaireRead } from "@/types/questionnaire/questionnaire";
20	
21	export const questionnaireAtom = atom<QuestionnaireRead | null>(null);
22	export const responsesAtom = atom<Record<string, QuestionnaireResponse>>({});
23	export const errorsAtom = atom<QuestionValidationError[]>([]);
24	export const activeGroupIndexAtom = atom(0);
25	
26	/** link_id → question_id, for enable_when lookups. */
27	export const questionIdByLinkIdAtom = atom((get) => {
28	  const questionnaire = get(questionnaireAtom);
29	  const index: Record<string, string> = {};
30	  const walk = (questions: Question[]) => {
31	    for (const question of questions) {
32	      index[question.link_id] = question.id;
33	      if (question.questions) walk(question.questions);
34	    }
35	  };
36	  if (questionnaire) walk(questionnaire.questions);
37	  return index;
38	});
39	
40	/** Flatten the tree into one response per non-group question, seeding
41	 *  initial_selected answer options (mirrors old initializeResponses). */
42	export function initializeResponses(
43	  questions: Question[],
44	): Record<string, QuestionnaireResponse> {
45	  const responses: Record<string, QuestionnaireResponse> = {};
46	  const walk = (qs: Question[]) => {
47	    for (const question of qs) {
48	      if (question.type === "group") {
49	        walk(question.questions ?? []);
50	        continue;
51	      }
52	      const initial: ResponseValue[] =
53	        question.answer_option && question.answer_option.length > 0
54	          ? question.answer_option
55	              .filter((option) => option.initial_selected)
56	              .map((option) => ({
57	                type: "string" as const,
58	                value: option.value,
59	                coding: option.code ?? undefined,
60	              }))
61	          : [];
62	      responses[question.id] = {
63	        question_id: question.id,
64	        structured_type: question.structured_type ?? null,
65	        link_id: question.link_id,
66	        values: initial,
67	      };
68	    }
69	  };
70	  walk(questions);
71	  return responses;
72	}
73	
74	/** Mirrors QuestionGroup.isQuestionEnabled's `normalizeValue` (old system):
75	 *  booleans normalize to "Yes"/"No", numbers stringify, before ANY operator
76	 *  is applied — matching the old code's unconditional normalization pass. */
77	function normalizeValue(value: unknown): unknown {
78	  if (typeof value === "boolean") return value ? "Yes" : "No";
79	  if (typeof value === "number") return value.toString();
80	  return value;
81	}
82	
83	/** Direct port of QuestionGroup.isQuestionEnabled's `checkCondition`
84	 *  (src/components/Questionnaire/QuestionTypes/QuestionGroup.tsx:37-103),
85	 *  operating on (enableWhen, response) instead of
86	 *  (enableWhen, questionnaireResponses). Preserves faithfully:
87	 *  - the unanswered-dependency short-circuit (no recorded values → false,
88	 *    for every operator, before any comparison runs)
89	 *  - evaluating against ALL of the dependent question's values (not just
90	 *    the first), via `.some()` / `.includes()` over the normalized values
91	 *  - normalizeValue being applied unconditionally before every operator */
92	export function evaluateEnableWhen(
93	  enableWhen: EnableWhen,
94	  response: QuestionnaireResponse | undefined,
95	): boolean {
96	  const dependentValues = response?.values;
97	
98	  if (!dependentValues || dependentValues.length === 0) return false;
99	
100	  const normalizedAnswers = dependentValues.map((v) => normalizeValue(v.value));
101	
102	  switch (enableWhen.operator) {
103	    case "exists":
104	      return (
105	        normalizedAnswers.length > 0 &&
106	        normalizedAnswers.some((v) => v !== "" && v !== null && v !== undefined)
107	      );
108	
109	    case "equals":
110	      // enableWhen.answer is boolean | string here (EnableWhenBoolean |
111	      // EnableWhenString). Legacy questionnaires store JSON true/false while
112	      // responses normalize to "Yes"/"No" — run the stored answer through
113	      // the same normalization so those conditions can ever match. (Only
114	      // literal booleans are normalized; string answers pass through
115	      // untouched, so non-boolean comparisons are unaffected.)
116	      return normalizedAnswers.includes(normalizeValue(enableWhen.answer));
117	
118	    case "not_equals":
119	      // enableWhen.answer is boolean | string here (EnableWhenBoolean | EnableWhenString)
120	      return !normalizedAnswers.includes(normalizeValue(enableWhen.answer));
121	
122	    case "greater":
123	      // enableWhen.answer is number here (EnableWhenNumeric)
124	      return normalizedAnswers.some(
125	        (v) => !isNaN(Number(v)) && Number(v) > enableWhen.answer,
126	      );
127	
128	    case "less":
129	      return normalizedAnswers.some(
130	        (v) => !isNaN(Number(v)) && Number(v) < enableWhen.answer,
131	      );
132	
133	    case "greater_or_equals":
134	      return normalizedAnswers.some(
135	        (v) => !isNaN(Number(v)) && Number(v) >= enableWhen.answer,
136	      );
137	
138	    case "less_or_equals":
139	      return normalizedAnswers.some(
140	        (v) => !isNaN(Number(v)) && Number(v) <= enableWhen.answer,
141	      );
142	
143	    default:
144	      return true;
145	  }
146	}
