148	export function useQuestionResponse(questionId: string) {
149	  const responseAtom = useMemo(
150	    () =>
151	      atom(
152	        (get) => get(responsesAtom)[questionId],
153	        (get, set, update: Partial<QuestionnaireResponse>) => {
154	          const previous = get(responsesAtom);
155	          const current = previous[questionId];
156	          if (!current) return;
157	          set(responsesAtom, {
158	            ...previous,
159	            [questionId]: { ...current, ...update },
160	          });
161	        },
162	      ),
163	    [questionId],
164	  );
165	  return useAtom(responseAtom);
166	}
