168	/** Shared enable_when resolution — extracted (unchanged semantics) so both
169	 *  useQuestionEnabled and the pagination hook below evaluate identically. */
170	function isQuestionEnabledInState(
171	  question: Question,
172	  responses: Record<string, QuestionnaireResponse>,
173	  linkIndex: Record<string, string>,
174	): boolean {
175	  if (!question.enable_when?.length) return true;
176	  const results = question.enable_when.map((condition) =>
177	    evaluateEnableWhen(
178	      condition,
179	      responses[linkIndex[condition.question] ?? ""],
180	    ),
181	  );
182	  return question.enable_behavior === "any"
183	    ? results.some(Boolean)
184	    : results.every(Boolean);
185	}
186	
187	export function useQuestionEnabled(question: Question): boolean {
188	  const enabledAtom = useMemo(
189	    () =>
190	      atom((get) =>
191	        isQuestionEnabledInState(
192	          question,
193	          get(responsesAtom),
194	          get(questionIdByLinkIdAtom),
195	        ),
196	      ),
197	    [question],
198	  );
199	  return useAtomValue(enabledAtom);
200	}
201	
202	/**
203	 * Indices of top-level questions that should take part in pagination.
204	 *
205	 * The legacy renderer showed the whole questionnaire in one scroll page, so
206	 * an enable_when-hidden question simply didn't appear — the paginated v2
207	 * renderer must skip those indices rather than serve blank pages.
208	 * `disabled_display: "protected"` questions stay included because
209	 * QuestionField still renders them (greyed) when disabled.
210	 */
211	export function useVisibleTopLevelIndices(): number[] {
212	  const visibleIndicesAtom = useMemo(
213	    () =>
214	      atom((get) => {
215	        const questionnaire = get(questionnaireAtom);
216	        if (!questionnaire) return [];
217	        const responses = get(responsesAtom);
218	        const linkIndex = get(questionIdByLinkIdAtom);
219	        const indices: number[] = [];
220	        questionnaire.questions.forEach((question, index) => {
221	          if (
222	            question.disabled_display === "protected" ||
223	            isQuestionEnabledInState(question, responses, linkIndex)
224	          ) {
225	            indices.push(index);
226	          }
227	        });
228	        return indices;
229	      }),
230	    [],
231	  );
232	  return useAtomValue(visibleIndicesAtom);
233	}
234	
235	/**
236	 * Ids of every question in the tree (any depth) currently hidden by its
237	 * enable_when conditions — i.e. disabled and not `disabled_display:
238	 * "protected"` (protected questions still render, greyed). The tree nav
239	 * uses this to drop rows for questions that don't exist on the page,
240	 * including nested children the top-level-only pagination set misses.
241	 */
242	export function useHiddenQuestionIds(): Set<string> {
243	  const hiddenIdsAtom = useMemo(
244	    () =>
245	      atom((get) => {
246	        const questionnaire = get(questionnaireAtom);
247	        const hidden = new Set<string>();
248	        if (!questionnaire) return hidden;
249	        const responses = get(responsesAtom);
250	        const linkIndex = get(questionIdByLinkIdAtom);
251	        const walk = (questions: Question[]) => {
252	          for (const question of questions) {
253	            if (
254	              question.disabled_display !== "protected" &&
255	              !isQuestionEnabledInState(question, responses, linkIndex)
256	            ) {
257	              hidden.add(question.id);
258	            }
259	            walk(question.questions ?? []);
260	          }
261	        };
262	        walk(questionnaire.questions);
263	        return hidden;
264	      }),
265	    [],
266	  );
267	  return useAtomValue(hiddenIdsAtom);
268	}
269	
270	export function useQuestionErrors(questionId: string) {
271	  const questionErrorsAtom = useMemo(
272	    () =>
273	      atom((get) =>
274	        get(errorsAtom).filter((error) => error.question_id === questionId),
275	      ),
276	    [questionId],
277	  );
278	  return useAtomValue(questionErrorsAtom);
279	}
