42	
43	export function collectIds(question: Question): string[] {
44	  return [question.id, ...(question.questions ?? []).flatMap(collectIds)];
45	}
46	
47	/**
48	 * Boolean conditions persist the strings "Yes"/"No" — never JSON booleans.
49	 * Both deployed evaluators (v2 store.evaluateEnableWhen and the legacy
50	 * QuestionGroup.isQuestionEnabled) normalize the dependent boolean *response*
51	 * to "Yes"/"No" before comparing, so a boolean (or "true"/"false") answer
52	 * could never match. Mirrors the legacy editor's migration for older
53	 * questionnaires that stored true/false ("temp fix for boolean answers in
54	 * existing questionnaires", QuestionnaireEditor.tsx). Lives here (not in
55	 * VisibilityConditionsCard) so the editor display path and the load-time
56	 * migration below can't drift.
57	 */
58	export function normalizeBooleanConditionAnswer(answer: unknown): "Yes" | "No" {
59	  if (answer === true || answer === "true" || answer === "Yes") return "Yes";
60	  return "No";
61	}
62	
63	/**
64	 * Repairs legacy boolean enable_when answers (JSON true/false or the strings
65	 * "true"/"false") to the deployed "Yes"/"No" convention, keyed off the
66	 * target question's type so string questions that legitimately answer
67	 * "true" are left alone. Runs on builder load ("reset"); the repair
68	 * persists with the next save. The renderer store additionally normalizes
69	 * boolean answers at evaluation time so already-saved questionnaires work
70	 * without a re-save.
71	 */
72	export function migrateLegacyBooleanEnableWhen(
73	  questions: Question[],
74	): Question[] {
75	  const typeByLinkId = new Map<string, Question["type"]>();
76	  const indexTypes = (list: Question[]) => {
77	    for (const question of list) {
78	      if (!typeByLinkId.has(question.link_id)) {
79	        typeByLinkId.set(question.link_id, question.type);
80	      }
81	      indexTypes(question.questions ?? []);
82	    }
83	  };
84	  indexTypes(questions);
85	
86	  const needsMigration = (condition: EnableWhen): boolean =>
87	    typeByLinkId.get(condition.question) === "boolean" &&
88	    (condition.operator === "equals" || condition.operator === "not_equals") &&
89	    (typeof condition.answer === "boolean" ||
90	      condition.answer === "true" ||
91	      condition.answer === "false");
92	
93	  return mapTree(questions, (list) =>
94	    list.map((question) => {
95	      if (!question.enable_when?.some(needsMigration)) return question;
96	      return {
97	        ...question,
98	        enable_when: question.enable_when.map((condition) =>
99	          needsMigration(condition)
100	            ? ({
101	                ...condition,
102	                answer: normalizeBooleanConditionAnswer(condition.answer),
103	              } as EnableWhen)
104	            : condition,
105	        ),
106	      };
107	    }),
108	  );
109	}
110	
111	/**
112	 * Resolves `ids` against `questions` and unions in every descendant id of
113	 * each match, so callers can reason about whole subtrees rather than just
114	 * the literal ids provided. Ids that cannot be found are skipped.
115	 */
116	function collectSubtreeIds(questions: Question[], ids: string[]): Set<string> {
117	  const result = new Set<string>();
118	  for (const id of ids) {
119	    const question = findQuestion(questions, id);
120	    if (!question) continue;
121	    for (const collected of collectIds(question)) {
122	      result.add(collected);
123	    }
124	  }
125	  return result;
126	}
127	
128	/** Immutably map every questions array in the tree (root included). */
129	export function mapTree(
130	  questions: Question[],
131	  fn: (list: Question[], parentId: string | null) => Question[],
132	  parentId: string | null = null,
133	): Question[] {
134	  return fn(questions, parentId).map((question) =>
135	    question.questions?.length || question.type === "group"
136	      ? {
137	          ...question,
138	          questions: mapTree(question.questions ?? [], fn, question.id),
139	        }
140	      : question,
141	  );
142	}
143	
144	export function builderReducer(
145	  state: BuilderState,
146	  action: BuilderAction,
147	): BuilderState {
148	  switch (action.type) {
149	    case "reset": {
150	      // Legacy boolean conditions are repaired on load; the fix lands with
151	      // the next save (state stays clean — dirty: false).
152	      const questions = migrateLegacyBooleanEnableWhen(action.questions);
153	      return {
154	        questions,
155	        // Selection is builder working state — a post-save reset keeps the
156	        // user's place when the previously selected question still exists.
157	        selectedId:
158	          action.keepSelectedId &&
159	          findQuestion(questions, action.keepSelectedId)
160	            ? action.keepSelectedId
161	            : (questions[0]?.id ?? null),
162	        dirty: false,
163	      };
164	    }
165	
166	    case "replaceAll":
167	      return {
168	        questions: action.questions,
169	        selectedId: action.questions[0]?.id ?? null,
170	        dirty: true,
171	      };
172	
173	    case "select":
174	      return { ...state, selectedId: action.id };
175	
176	    case "addQuestion": {
177	      const question = newQuestion();
178	      const questions = mapTree(state.questions, (list, parentId) => {
179	        if (parentId !== action.parentId) return list;
180	        const index = action.index ?? list.length;
181	        return [...list.slice(0, index), question, ...list.slice(index)];
182	      });
183	      return { questions, selectedId: question.id, dirty: true };
184	    }
185	
186	    case "updateQuestion": {
187	      const questions = mapTree(state.questions, (list) =>
188	        list.map((q) => (q.id === action.id ? { ...q, ...action.patch } : q)),
189	      );
190	      return { ...state, questions, dirty: true };
191	    }
192	
193	    case "removeQuestions": {
194	      const ids = new Set(action.ids);
195	      const removedIds = collectSubtreeIds(state.questions, action.ids);
196	      const questions = mapTree(state.questions, (list) =>
197	        list.filter((q) => !ids.has(q.id)),
198	      );
199	      return {
200	        questions,
201	        selectedId: removedIds.has(state.selectedId ?? "")
202	          ? (questions[0]?.id ?? null)
203	          : state.selectedId,
204	        dirty: true,
205	      };
206	    }
207	
208	    case "moveQuestion": {
209	      const questions = mapTree(state.questions, (list) => {
210	        const index = list.findIndex((q) => q.id === action.id);
211	        if (index === -1) return list;
212	        const target = action.direction === "up" ? index - 1 : index + 1;
213	        if (target < 0 || target >= list.length) return list;
214	        const next = [...list];
215	        [next[index], next[target]] = [next[target], next[index]];
216	        return next;
217	      });
218	      return { ...state, questions, dirty: true };
219	    }
220	
221	    case "moveQuestions": {
222	      const movedSubtreeIds = collectSubtreeIds(state.questions, action.ids);
223	      if (
224	        action.targetParentId !== null &&
225	        movedSubtreeIds.has(action.targetParentId)
226	      ) {
227	        // Target is the moved question itself or one of its descendants —
228	        // that parent won't exist anymore once the subtree is excised, so
229	        // moving there would silently drop the data. No-op instead.
230	        return state;
231	      }
232	
233	      const ids = new Set(action.ids);
234	      const moved: Question[] = [];
235	      const walk = (list: Question[]) => {
236	        for (const q of list) {
237	          if (ids.has(q.id)) {
238	            moved.push(q);
239	            continue;
240	          }
241	          walk(q.questions ?? []);
242	        }
243	      };
244	      walk(state.questions);
245	      const withoutMoved = mapTree(state.questions, (list) =>
246	        list.filter((q) => !ids.has(q.id)),
247	      );
248	      const questions = mapTree(withoutMoved, (list, parentId) => {
249	        if (parentId !== action.targetParentId) return list;
250	        const index = Math.min(action.index, list.length);
251	        return [...list.slice(0, index), ...moved, ...list.slice(index)];
252	      });
253	      return { ...state, questions, dirty: true };
254	    }
255	  }
256	}
257

1	import { Provider as JotaiProvider, createStore } from "jotai";
2	import { createContext, useContext, useEffect, useRef, useState } from "react";
3	
4	import { QuestionnaireRead } from "@/types/questionnaire/questionnaire";
5	
6	import {
7	  activeGroupIndexAtom,
8	  initializeResponses,
9	  questionnaireAtom,
10	  responsesAtom,
11	} from "./store";
12	import { RendererMode, RendererSubject } from "./types";
13	
14	interface RendererContextValue {
15	  mode: RendererMode;
16	  subject: RendererSubject;
17	  questionnaire: QuestionnaireRead;
18	}
19	
20	const RendererContext = createContext<RendererContextValue | null>(null);
21	
22	export function useRenderer(): RendererContextValue {
23	  const context = useContext(RendererContext);
24	  if (!context) {
25	    throw new Error(
26	      "useRenderer must be used inside QuestionnaireRendererProvider",
27	    );
28	  }
29	  return context;
30	}
31	
32	interface ProviderProps {
33	  questionnaire: QuestionnaireRead;
34	  mode: RendererMode;
35	  subject?: RendererSubject;
36	  children: React.ReactNode;
37	}
38	
39	export function QuestionnaireRendererProvider({
40	  questionnaire,
41	  mode,
42	  subject = {},
43	  children,
44	}: ProviderProps) {
45	  // useState (not useMemo) guarantees the store is created exactly once per
46	  // component instance — React may discard a useMemo cache under memory
47	  // pressure, which would silently recreate the store and wipe any
48	  // in-progress answers. Seeding happens inside the initializer so the store
49	  // is never observed empty: derived selectors (useVisibleTopLevelIndices,
50	  // useQuestionResponse, …) would otherwise see questionnaireAtom === null
51	  // for the first render and blank the whole preview for one paint.
52	  const [store] = useState(() => {
53	    const seeded = createStore();
54	    seeded.set(questionnaireAtom, questionnaire);
55	    seeded.set(responsesAtom, initializeResponses(questionnaire.questions));
56	    return seeded;
57	  });
58	
59	  // Re-seed only when the questionnaire identity changes after mount (the
60	  // builder preview passes a fresh draft object on each Edit→Preview
61	  // switch); the ref guard keeps the initial mount from re-running the seed.
62	  const seededQuestionnaire = useRef(questionnaire);
63	  useEffect(() => {
64	    if (seededQuestionnaire.current === questionnaire) return;
65	    seededQuestionnaire.current = questionnaire;
66	    store.set(questionnaireAtom, questionnaire);
67	    store.set(responsesAtom, initializeResponses(questionnaire.questions));
68	    store.set(activeGroupIndexAtom, 0);
69	  }, [questionnaire, store]);
70	
71	  return (
72	    // Context carries the immutable mount config (mode/subject/questionnaire
73	    // identity); the atoms above are the reactive copy every selector reads.
74	    <RendererContext.Provider value={{ mode, subject, questionnaire }}>
75	      <JotaiProvider store={store}>{children}</JotaiProvider>
76	    </RendererContext.Provider>
77	  );
78	}
