export const meta = {
  name: 'questionnaire-builder-recon',
  description: 'Map QuestionnaireV2 + legacy questionnaire internals to inform the WYSIWYG builder redesign',
  phases: [{ title: 'Explore', detail: 'six parallel readers over the frontend' }],
}

const SCHEMA = {
  type: 'object',
  properties: {
    summary: { type: 'string', description: 'Dense prose summary of findings, 300-800 words' },
    files: { type: 'array', items: { type: 'object', properties: {
      path: { type: 'string' },
      role: { type: 'string', description: 'one-line: what it does, key exports/props' },
      reuse: { type: 'string', enum: ['reuse-as-is', 'adapt', 'replace', 'reference-only'] },
    }, required: ['path', 'role', 'reuse'] } },
    contracts: { type: 'array', items: { type: 'string' }, description: 'Invariants/gotchas the new code must honor' },
  },
  required: ['summary', 'files', 'contracts'],
}

const READERS = [
  { key: 'builder', prompt: `Read EVERY file in /Users/bodhishthomas/code/care_fe/src/components/QuestionnaireV2/builder/ (QuestionnaireBuilderPage.tsx, QuestionEditorCard.tsx, BuilderTreeNav.tsx, EditPreviewToggle.tsx, saveValidation.ts, AnswerOptionsEditor.tsx, QuestionTypePicker.tsx, VisibilityConditionsCard.tsx, QuestionCodingCard.tsx, BehaviourSettingsCard.tsx, SubQuestionsList.tsx, BuilderEmptyState.tsx, ImportQuestionsDialog.tsx, MoveQuestionsDialog.tsx) plus shared/ files they import (QuestionTreeNav, questionTree.ts, buildUpdateBody.ts, questionTypeIcons.ts, QuestionTypeBadge, CollapsibleSettingsCard, SegmentedRadioGroup, ChoiceChip, LabeledActionButton, useValueSetExpansion). Report: the builder page layout/shell structure (how save/discard/preview work, how state flows reducer->cards), each editor card's props + what question fields it edits, which pieces are self-contained enough to be rehosted inside a new right-hand inspector panel (report per-file reuse verdicts for a redesign where the builder becomes 3-pane: left outline tree, center WYSIWYG canvas, right inspector). Note all data-cy/test-id attributes used. Note i18n key patterns.` },
  { key: 'renderer', prompt: `Read EVERY file in /Users/bodhishthomas/code/care_fe/src/components/QuestionnaireV2/renderer/ (QuestionnaireRenderer.tsx, RendererContext.tsx, store.ts, types.ts, QuestionField.tsx, QuestionGroupCard.tsx, TopLevelCard.tsx, RendererFooter.tsx, NoteAffordance.tsx, questionTypeRegistry.tsx, sanitizeStylingClasses.ts, structured/StructuredQuestionSlot.tsx, structured/registry.tsx, all files in inputs/). Report: the exact RendererInputProps contract, how QuestionField dispatches type->input and handles repeats/valueIndex/read_only/units/styling_metadata, how groups render (containerClasses), how StructuredQuestionSlot builds the legacy prop bag and what props legacy structured components need, how errors/notes are surfaced, what the pagination/TopLevelCard/RendererFooter do. Assess: what would need to change for (a) an all-sections-on-one-scroll canvas layout instead of pagination, (b) live question-tree updates on every keystroke from a builder (store re-seed semantics, response preservation), (c) a per-question decoration/wrapper injection point so a builder canvas can add selection chrome. Report reuse verdicts per file for building a NEW separate renderer module that reuses inputs where possible.` },
  { key: 'manage', prompt: `Read /Users/bodhishthomas/code/care_fe/src/components/QuestionnaireV2/manage/*.tsx and .ts (QuestionnaireDetailPage, FormPropertiesSidebar, questionnaireFormSchema.ts, useUpdateQuestionnaire.ts, BasicInformationCard, VersionsTab, QuestionnaireRevisionPage, QuestionnaireListPage, QuestionnaireCreatePage, CloneQuestionnaireDialog, OrganizationsField, QuestionOverviewList), plus /Users/bodhishthomas/code/care_fe/src/components/QuestionnaireV2/queryKeys.ts, useCanWriteQuestionnaire.ts, shared/buildUpdateBody.ts, /Users/bodhishthomas/code/care_fe/src/types/questionnaire/questionnaire.ts and questionnaireApi.ts, and the route registrations in /Users/bodhishthomas/code/care_fe/src/Routers/routes/adminRoutes.tsx and /Users/bodhishthomas/code/care_fe/src/pages/Facility/settings/layout.tsx (questionnaire parts only). Report: QuestionnaireScope shape and mounting, the detail page structure and how the edit route/builder is entered, every questionnaire-level field editable today (title/slug/description/status/subject_type/organizations/tags?), how versions/revisions work (list, view, what publish means today — is save=new revision?), the save mutation flow (buildUpdateBody, setQueryData), status values, and the API routes available (incl. revision endpoints). Note which questionnaire-level editing surfaces could move into a builder right-panel "Form settings" inspector.` },
  { key: 'legacy', prompt: `Read /Users/bodhishthomas/code/care_fe/src/components/Questionnaire/QuestionnaireForm.tsx, QuestionRenderer.tsx, QuestionTypes/QuestionGroup.tsx, QuestionTypes/QuestionInput.tsx if present, and skim the structured components referenced by /Users/bodhishthomas/code/care_fe/src/components/QuestionnaireV2/renderer/structured/registry.tsx (AllergyQuestion, MedicationRequestQuestion, SymptomQuestion, DiagnosisQuestion, EncounterQuestion, FileQuestion, AppointmentQuestion, ChargeItemQuestion, ServiceRequestQuestion, MedicationStatementQuestion, DeathQuestion) — focus on their shared props (question, questionnaireResponse, updateQuestionnaireResponseCB, disabled, errors, clearError, index, withLabel, patientId, encounterId, facilityId) and any hooks they call that require providers (react-hook-form FormProvider? TanStack query? PermissionContext?). Also read /Users/bodhishthomas/code/care_fe/src/components/Questionnaire/data/StructuredFormData.ts and /Users/bodhishthomas/code/care_fe/src/types/questionnaire/form.ts and batch.ts. Report: what mounting a structured component outside an encounter page requires, how the legacy fill flow submits (batch requests API), where QuestionnaireForm is mounted from (encounter routes), and anything (toasts, navigation side effects) structured components do that a builder-preview host must guard against.` },
  { key: 'tokens', prompt: `In /Users/bodhishthomas/code/care_fe: read src/index.css (or wherever Tailwind v4 theme/design tokens live — search for '@theme' or ':root' CSS variable definitions), tailwind config if any, and care.config.ts theme parts. The reference design uses CSS vars: --background, --soft-background, --muted-background, --strong-background, --border, --soft-border, --strong-border, --input, --foreground, --soft-foreground, --muted-foreground, --placeholder-foreground, --disabled-foreground, --primary, --primary-foreground, --popover, --card, --destructive, --color-emerald-50/700/900, --color-amber-50/700, --color-indigo-50/700, --color-sky-50/700, --color-teal-50/700, --color-red-50/700, --color-neutral-300. Report which exist in care_fe (exact names or closest Tailwind v4 equivalents/utility classes used in the codebase, e.g. bg-gray-50 vs var(--soft-background)), what the primary color is, which shadcn/ui components exist in src/components/ui/ (list the directory), and the conventional patterns for popovers/dropdowns/toggles/tabs/segmented controls in this codebase (Radix wrappers available).` },
  { key: 'tests', prompt: `In /Users/bodhishthomas/code/care_fe/tests: list all spec files under facility/settings/questionnaires/ and admin/questionnaires/, and read tests/helper/questionnaireV2.ts fully plus skim 3-4 representative builder specs (authoring matrix, navigation, visibility conditions, group tooling). Report: which specs exercise the BUILDER edit page UI (and would break if the builder page UX is replaced with a 3-pane canvas+inspector design) vs which exercise list/create/detail/versions/preview (safe). For builder specs, list the helper functions and selectors (getByRole/text/data-cy) they rely on, so a redesigned builder can either keep affordances compatible or the specs can be mechanically updated. Also report how tests reach the builder (URL pattern) and any fixtures used.` },
]

phase('Explore')
const results = await parallel(READERS.map(r => () =>
  agent(r.prompt + '\n\nReturn via StructuredOutput. Be exhaustive on contracts and precise on file paths. You are read-only: do not edit anything.', { label: 'read:' + r.key, schema: SCHEMA, agentType: 'Explore' })
))

return Object.fromEntries(READERS.map((r, i) => [r.key, results[i]]))

