58	export function QuestionnaireBuilderPage({
59	  scope,
60	  id,
61	}: {
62	  scope: QuestionnaireScope;
63	  id: string;
64	}) {
65	  const { t } = useTranslation();
66	
67	  const {
68	    data: questionnaire,
69	    isLoading,
70	    isError,
71	  } = useQuery({
72	    queryKey: questionnaireKeys.detail(id),
73	    queryFn: query(questionnaireApi.get, { pathParams: { id } }),
74	  });
75	
76	  const [state, dispatch] = useReducer(builderReducer, INITIAL_STATE);
77	
78	  useEffect(() => {
79	    // Skip while the user has unsaved edits (`state.dirty`) — otherwise a
80	    // background refetch that returns a new `questionnaire` reference (e.g.
81	    // refetchOnReconnect after a network blip) would silently discard them.
82	    // The post-save path resets explicitly (see the mutation's onSuccess
83	    // below) after dirty has already been cleared, so this guard doesn't
84	    // block that path.
85	    if (questionnaire && !state.dirty) {
86	      dispatch({
87	        type: "reset",
88	        questions: questionnaire.questions,
89	        keepSelectedId: state.selectedId,
90	      });
91	    }
92	    // eslint-disable-next-line react-hooks/exhaustive-deps
93	  }, [questionnaire]);
94	
95	  const [queryParams, setQueryParams] = useQueryParams();
96	  const { mode, import: importParam } = queryParams;
97	  const [view, setView] = useState<"edit" | "preview">(
98	    mode === "preview" ? "preview" : "edit",
99	  );
100	  const [importOpen, setImportOpen] = useState(importParam === "1");
101	
102	  useEffect(() => {
103	    // The dialog's open state above already captured `?import=1` — strip it
104	    // from the URL (preserving any other params, e.g. `mode`) so a refresh
105	    // or Back navigation doesn't reopen the dialog.
106	    if (importParam !== "1") return;
107	    const { import: _import, ...rest } = queryParams;
108	    setQueryParams(rest, { overwrite: true, replace: true });
109	    // eslint-disable-next-line react-hooks/exhaustive-deps
110	  }, []);
111	
112	  useNavigationPrompt(state.dirty, t("unsaved_changes_warning"));
113	
114	  const { canWrite, isLoading: isPermissionLoading } =
115	    useCanWriteQuestionnaire(scope);
116	
117	  // Stable identity across unrelated re-renders (e.g. isPending flips) —
118	  // QuestionnaireRendererProvider re-seeds (wiping in-progress preview
119	  // answers) whenever this object's identity changes, so it must only change
120	  // when the draft actually does.
121	  const previewQuestionnaire = useMemo(
122	    () =>
123	      questionnaire
124	        ? { ...questionnaire, questions: state.questions }
125	        : undefined,
126	    [questionnaire, state.questions],
127	  );
128	
129	  // Owns the setQueryData-before-invalidate cache sequence and the success
130	  // toast (see the hook's doc comment); onSaved keeps the user's place in
131	  // the editor instead of bouncing to question 1.
132	  const { mutate: save, isPending } = useUpdateQuestionnaire(id, (updated) =>
133	    dispatch({
134	      type: "reset",
135	      questions: updated.questions,
136	      keepSelectedId: state.selectedId,
137	    }),
138	  );
139	
140	  const backPath = `${scope.basePath}/${id}`;
141	
142	  const handleSave = () => {
143	    if (!questionnaire) return;
144	
145	    // Rules live in saveValidation.ts; the first failing question is
146	    // selected and shown in edit view so the author can fix it.
147	    const invalid = findFirstInvalidQuestion(state.questions);
148	    if (invalid) {
149	      toast.error(t(invalid.messageKey));
150	      dispatch({ type: "select", id: invalid.question.id });
151	      setView("edit");
152	      return;
153	    }
154	
155	    save(buildUpdateBody(questionnaire, { questions: state.questions }));
156	  };
157	
158	  // isPermissionLoading folds in so write affordances (Save Changes, Import)
159	  // don't pop in after the facility query resolves.
160	  if (isLoading || isPermissionLoading) {
161	    return <FormSkeleton rows={10} />;
162	  }
163	
164	  if (isError || !questionnaire) {
165	    return (
166	      <div className="space-y-4">
167	        <Alert variant="destructive">
168	          <AlertTitle>{t("error")}</AlertTitle>
169	          <AlertDescription>{t("no_data_found")}</AlertDescription>
170	        </Alert>
171	        <Button variant="outline" onClick={() => navigate(scope.basePath)}>
172	          <ArrowLeft className="size-4" />
173	          {t("back")}
174	        </Button>
175	      </div>
176	    );
177	  }
178	
179	  const selectedQuestion = state.selectedId
180	    ? findQuestion(state.questions, state.selectedId)
181	    : undefined;
182	  const topLevelIndex = state.selectedId
183	    ? findTopLevelIndex(state.questions, state.selectedId)
184	    : 0;
185	  const canGoPrevious = topLevelIndex > 0;
186	  const canGoNext = topLevelIndex < state.questions.length - 1;
187	  // The selected question's own dotted number (e.g. "3.1." for a nested
188	  // child) — falls back to the top-level ancestor's ordinal for questions
189	  // nested deeper than `findQuestionNumber` numbers (grandchildren+).
190	  const selectedNumber =
191	    (state.selectedId &&
192	      findQuestionNumber(state.questions, state.selectedId)) ||
193	    `${topLevelIndex + 1}.`;
194	
195	  return (
196	    <div className="space-y-4">
197	      <div className="flex flex-wrap items-center justify-between gap-3">
198	        <div className="flex flex-wrap items-center gap-3">
199	          <Button
200	            type="button"
201	            variant="outline"
202	            size="xs"
203	            onClick={() => navigate(backPath)}
204	          >
205	            <ArrowLeft className="size-4" />
206	            {t("back")}
207	          </Button>
208	          <EditPreviewToggle view={view} onChange={setView} />
209	        </div>
210	        <div className="flex items-center gap-4">
211	          <Button
212	            type="button"
213	            variant="link"
214	            className="underline"
215	            onClick={() => navigate(backPath)}
216	          >
217	            {t("cancel")}
218	          </Button>
219	          {canWrite && (
220	            <Button
221	              type="button"
222	              onClick={handleSave}
223	              disabled={!state.dirty || isPending}
224	            >
225	              <Check className="size-4" />
226	              {t("save_changes")}
227	            </Button>
228	          )}
229	        </div>
230	      </div>
231	
232	      {view === "edit" ? (
233	        <div className="flex flex-col gap-4 md:flex-row">
234	          <div className="hidden w-72 shrink-0 self-start md:sticky md:top-4 md:block md:max-h-[calc(100vh-2rem)] md:overflow-y-auto">
235	            <BuilderTreeNav
236	              title={questionnaire.title}
237	              questions={state.questions}
238	              selectedId={state.selectedId}
239	              dispatch={dispatch}
240	            />
241	          </div>
242	          {/* Mobile fallback for the tree nav (hidden below md) — without it
243	              a phone user who drills into a nested sub-question has no way
244	              back to the parent or its siblings. */}
245	          {state.questions.length > 0 && (
246	            <div className="md:hidden">
247	              <Select
248	                value={state.selectedId ?? undefined}
249	                onValueChange={(selectedId) =>
250	                  dispatch({ type: "select", id: selectedId })
251	                }
252	              >
253	                <SelectTrigger className="w-full">
254	                  <SelectValue placeholder={t("select_question")} />
255	                </SelectTrigger>
256	                <SelectContent>
257	                  {numberQuestions(state.questions).flatMap((item) =>
258	                    [item, ...item.children].map(({ question, number }) => (
259	                      <SelectItem key={question.id} value={question.id}>
260	                        {number} {question.text || t("untitled_question")}
261	                      </SelectItem>
262	                    )),
263	                  )}
264	                </SelectContent>
265	              </Select>
266	            </div>
267	          )}
268	          <div className="min-w-0 flex-1 space-y-4">
269	            {selectedQuestion ? (
270	              <QuestionEditorCard
271	                question={selectedQuestion}
272	                number={selectedNumber}
273	                allQuestions={state.questions}
274	                dispatch={dispatch}
275	              />
276	            ) : (
277	              <BuilderEmptyState
278	                onAddFirst={() =>
279	                  dispatch({ type: "addQuestion", parentId: null })
280	                }
281	                onImport={canWrite ? () => setImportOpen(true) : undefined}
282	              />
283	            )}
284	
285	            {state.questions.length > 0 && (
286	              <div className="sticky bottom-0 flex flex-wrap items-center gap-2 border-t border-gray-200 bg-white px-2 py-3 sm:px-4">
287	                <Button
288	                  type="button"
289	                  variant="ghost"
290	                  size="sm"
291	                  className="shrink-0"
292	                  disabled={!canGoPrevious}
293	                  aria-label={t("previous")}
294	                  onClick={() =>
295	                    dispatch({
296	                      type: "select",
297	                      id: state.questions[topLevelIndex - 1].id,
298	                    })
299	                  }
300	                >
301	                  <ChevronLeft className="size-4" />
302	                  <span className="hidden sm:inline">{t("previous")}</span>
303	                </Button>
304	                <Button
305	                  type="button"
306	                  variant="outline_primary"
307	                  className="min-w-0 flex-1"
308	                  onClick={() =>
309	                    dispatch({ type: "addQuestion", parentId: null })
310	                  }
311	                >
312	                  <Plus className="size-4" />
313	                  {t("add_new_question")}
314	                </Button>
315	                <Button
316	                  type="button"
317	                  variant="ghost"
318	                  size="sm"
319	                  className="shrink-0"
320	                  disabled={!canGoNext}
321	                  aria-label={t("next")}
322	                  onClick={() =>
323	                    dispatch({
324	                      type: "select",
325	                      id: state.questions[topLevelIndex + 1].id,
326	                    })
327	                  }
328	                >
329	                  <span className="hidden sm:inline">{t("next")}</span>
330	                  <ChevronRight className="size-4" />
331	                </Button>
332	              </div>
333	            )}
334	          </div>
335	        </div>
336	      ) : (
337	        previewQuestionnaire && (
338	          <QuestionnaireRenderer
339	            questionnaire={previewQuestionnaire}
340	            mode="preview"
341	            subject={{ facilityId: scope.facilityId }}
342	          />
343	        )
344	      )}
345	
346	      {/* canWrite also guards the ?import=1 deep link for read-only users. */}
347	      {canWrite && (
348	        <ImportQuestionsDialog
349	          open={importOpen}
350	          onOpenChange={setImportOpen}
351	          onImport={(questions) => {
352	            dispatch({ type: "replaceAll", questions });
353	            toast.success(t("questionnaire_imported_successfully"));
354	          }}
355	        />
356	      )}
357	    </div>
358	  );
359	}
