25	export function QuestionField({
26	  question,
27	  depth,
28	  number,
29	}: {
30	  question: Question;
31	  depth: number;
32	  /** Dotted ordinal matching the tree nav (e.g. "8." or "7.1."). */
33	  number?: string;
34	}) {
35	  const { t } = useTranslation();
36	  const { mode } = useRenderer();
37	  const enabled = useQuestionEnabled(question);
38	  const errors = useQuestionErrors(question.id);
39	  // Only read for repeating questions (groups have no response entry).
40	  const [response, updateResponse] = useQuestionResponse(question.id);
41	  const disabled = mode === "readonly" || question.read_only === true;
42	
43	  if (!enabled && question.disabled_display !== "protected") return null;
44	  const effectiveDisabled = disabled || !enabled;
45	
46	  if (question.type === "group") {
47	    return (
48	      <QuestionGroupCard
49	        question={question}
50	        depth={depth}
51	        disabled={effectiveDisabled}
52	        number={number}
53	      />
54	    );
55	  }
56	
57	  const InputComponent = QUESTION_TYPE_COMPONENTS[question.type];
58	  // Programmatic label association: text-like inputs take `id={inputId}` for
59	  // the htmlFor pairing; chip groups (boolean/choice) reference `labelId`
60	  // via aria-labelledby on their radiogroup container instead.
61	  const inputId = `question-input-${question.id}`;
62	  const labelId = `question-label-${question.id}`;
63	
64	  // Chip groups (boolean/choice-with-options) sit directly on the card
65	  // background — wrapping them in a full-width bordered box would read as an
66	  // empty text input next to the chips.
67	  const isChipInput =
68	    question.type === "boolean" ||
69	    (question.type === "choice" && !!question.answer_option?.length);
70	
71	  // Repeats → one input per value entry (legacy QuestionInput's per-index
72	  // rendering). Choice handles repeats itself (multi-select chips),
73	  // structured questions manage their own arrays, and display has no values
74	  // to repeat — those keep the single-input path.
75	  const isMultiEntry =
76	    !!InputComponent &&
77	    question.repeats === true &&
78	    question.type !== "structured" &&
79	    question.type !== "choice" &&
80	    question.type !== "display";
81	
82	  const entryCount = Math.max(response?.values.length ?? 0, 1);
83	  const canRemoveEntries = (response?.values.length ?? 0) > 1;
84	
85	  // Mirrors the legacy handleAddValue: adding from an empty response
