87	  // swallows the one the user was looking at.
88	  const handleAddEntry = () => {
89	    const current = response?.values ?? [];
90	    const next = current.length === 0 ? [emptyEntry()] : [...current];
91	    next.push(emptyEntry());
92	    updateResponse({ values: next });
93	  };
94	
95	  const handleRemoveEntry = (index: number) => {
96	    updateResponse({
97	      values: (response?.values ?? []).filter((_, i) => i !== index),
98	    });
