100	
101	  const field = (
102	    <div
103	      className={cn(
104	        "space-y-1.5",
105	        // Questionnaire-authored classes — sanitized, never raw.
106	        sanitizeStylingClasses(question.styling_metadata?.containerClasses),
107	      )}
108	    >
109	      <div className="flex items-center gap-2">
110	        {number && (
111	          <span className="shrink-0 text-sm font-medium text-gray-800 tabular-nums">
112	            {number}
113	          </span>
114	        )}
115	        <label
116	          id={labelId}
117	          htmlFor={inputId}
118	          className="text-sm font-medium text-gray-800"
119	        >
120	          {question.text}
121	        </label>
122	        {question.required && <span className="text-red-500">*</span>}
