132	      )}
133	      {question.type === "structured" ? (
134	        <StructuredQuestionSlot
135	          question={question}
136	          disabled={effectiveDisabled}
137	        />
138	      ) : isMultiEntry ? (
139	        <div className="space-y-2">
140	          {Array.from({ length: entryCount }, (_, index) => (
141	            <div key={index} className="flex items-center gap-2">
142	              <div
143	                className={cn(
144	                  "min-w-0 flex-1",
145	                  !isChipInput &&
146	                    "overflow-hidden rounded-md border border-gray-200 bg-white",
147	                )}
148	              >
149	                <InputComponent
150	                  question={question}
151	                  disabled={effectiveDisabled}
152	                  inputId={index === 0 ? inputId : `${inputId}-${index}`}
