154	                  valueIndex={index}
155	                />
156	              </div>
157	              {canRemoveEntries && (
158	                <Button
159	                  type="button"
160	                  variant="ghost"
161	                  size="icon"
162	                  className="shrink-0"
163	                  disabled={effectiveDisabled}
164	                  onClick={() => handleRemoveEntry(index)}
165	                  aria-label={t("remove")}
166	                >
167	                  <X className="size-4" />
168	                </Button>
169	              )}
170	            </div>
171	          ))}
172	          <div className="flex items-center gap-2">
173	            <Button
174	              type="button"
175	              variant="outline"
176	              size="sm"
177	              disabled={effectiveDisabled}
178	              onClick={handleAddEntry}
179	            >
180	              <Plus className="size-4" />
181	              {t("add_another")}
182	            </Button>
183	            <NoteAffordance questionId={question.id} variant="standalone" />
184	          </div>
185	        </div>
186	      ) : (
187	        <div
188	          className={cn(
189	            "flex items-stretch",
190	            !isChipInput &&
191	              "overflow-hidden rounded-md border border-gray-200 bg-white",
192	          )}
193	        >
194	          <div className="min-w-0 flex-1">
195	            {InputComponent ? (
196	              <InputComponent
197	                question={question}
198	                disabled={effectiveDisabled}
199	                inputId={inputId}
200	                labelId={labelId}
201	              />
202	            ) : (
203	              <p className="p-2 text-sm italic text-gray-400">
204	                {t("unsupported_question_type")}
205	              </p>
206	            )}
207	          </div>
208	          {question.type !== "display" && (
209	            <NoteAffordance
210	              questionId={question.id}
211	              variant={isChipInput ? "standalone" : "merged"}
212	            />
213	          )}
214	        </div>
215	      )}
216	      {errors.map((error, i) => (
217	        <p key={i} className="text-sm text-red-600">
218	          {error.msg ?? error.error}
219	        </p>
220	      ))}
221	    </div>
222	  );
223	
224	  // Top-level plain questions get the same card shell as top-level groups.
225	  if (depth === 0) {
226	    return <TopLevelCard>{field}</TopLevelCard>;
227	  }
228	
229	  return field;
230	}
