13	export function QuestionGroupCard({
14	  question,
15	  depth,
16	  disabled,
17	  number,
18	}: {
19	  question: Question;
20	  depth: number;
21	  disabled: boolean;
22	  /** Dotted ordinal matching the tree nav (e.g. "7."); children derive
23	   *  "7.1.", "7.2.", … from it. */
24	  number?: string;
25	}) {
26	  const { t } = useTranslation();
27	  const children = question.questions ?? [];
28	  const leafChildCount = children.filter(
29	    (child) => child.type !== "group",
30	  ).length;
31	
32	  // styling_metadata is questionnaire-authored (it arrives via imported
33	  // JSON) — sanitize before splicing into className. `classes` decorates the
34	  // card wrapper; `containerClasses` carries the layout preset for the
35	  // sub-question container (the deployed contract shared with the legacy
36	  // editor/renderer).
37	  const decorationClasses = sanitizeStylingClasses(
38	    question.styling_metadata?.classes,
39	  );
40	  const containerClasses = sanitizeStylingClasses(
41	    question.styling_metadata?.containerClasses,
42	  );
43	
44	  const childNumber = (index: number) =>
45	    number ? `${number}${index + 1}.` : undefined;
46	
47	  if (depth === 0) {
48	    return (
49	      <TopLevelCard className={decorationClasses}>
50	        <div className="flex items-center gap-2">
51	          <h3 className="text-sm font-semibold text-gray-900">
