62	          className={cn(
63	            "border-0 p-0",
64	            containerClasses ? cn("gap-4", containerClasses) : "space-y-4",
65	          )}
66	        >
67	          {children.map((child, index) => (
68	            <QuestionField
69	              key={child.id}
70	              question={child}
71	              depth={depth + 1}
72	              number={childNumber(index)}
73	            />
74	          ))}
75	        </fieldset>
76	      </TopLevelCard>
77	    );
78	  }
79	
80	  // Nested group: two-tone box — the title sits in its own darker header
81	  // strip with a lighter inset body panel beneath it.
82	  return (
83	    <div
84	      className={cn(
85	        "overflow-hidden rounded-md border border-gray-200 bg-gray-200/60",
86	        decorationClasses,
87	      )}
88	    >
89	      <h4 className="px-3 py-1.5 text-sm font-semibold text-gray-900">
