96	          "m-1 gap-4 rounded border-0 bg-gray-50 p-2",
97	          containerClasses ??
98	            cn("grid sm:grid-cols-2", leafChildCount >= 3 && "sm:grid-cols-3"),
99	        )}
100	      >
101	        {children.map((child, index) => (
102	          <QuestionField
103	            key={child.id}
104	            question={child}
105	            depth={depth + 1}
