10	
11	export interface QuestionTreeNavProps {
12	  title?: string;
13	  questions: Question[];
14	  activeId: string | null;
15	  onSelect: (questionId: string) => void;
16	  footer?: React.ReactNode;
17	  /** Builder-only affordances (insert-between "+" buttons etc.) */
18	  renderSeparator?: (afterIndex: number) => React.ReactNode;
19	  /** Question ids (any depth) currently hidden by enable_when (renderer
20	   *  only) — skipped entirely, matching the legacy renderer where hidden
21	   *  questions simply don't appear. Numbering stays stable across hides. */
22	  hiddenIds?: Set<string>;
23	}
24	
25	export function QuestionTreeNav({
26	  title,
27	  questions,
28	  activeId,
29	  onSelect,
30	  footer,
31	  renderSeparator,
32	  hiddenIds,
33	}: QuestionTreeNavProps) {
34	  const { t } = useTranslation();
35	  const items = numberQuestions(questions).filter(
36	    (item) => !hiddenIds?.has(item.question.id),
37	  );
38	
39	  const row = (item: TreeItem, indent: boolean) => {
40	    const { icon: TypeIcon, tint } = QUESTION_TYPE_ICONS[item.question.type];
41	    return (
42	      <button
43	        key={item.question.id}
44	        type="button"
45	        onClick={() => onSelect(item.question.id)}
46	        className={cn(
47	          "relative flex w-full items-start gap-1 rounded-md px-3 py-2 text-left text-sm",
48	          indent && "ml-2",
49	          activeId === item.question.id
50	            ? "bg-gray-100 font-medium text-gray-900"
51	            : "text-gray-700 hover:bg-gray-50",
52	        )}
53	      >
54	        <span className="shrink-0">{item.number}</span>
55	        {/* Decorative type recognition cue — aria-hidden keeps row names
56	            (number + title) unchanged for a11y and specs. */}
57	        <span
58	          aria-hidden
59	          className={cn(
60	            "mt-px flex size-4 shrink-0 items-center justify-center rounded-sm",
61	            tint,
62	          )}
63	        >
64	          <TypeIcon className="size-3" />
65	        </span>
66	        <span className="min-w-0">
67	          {item.question.text || (
68	            <span className="italic text-gray-400">
69	              {t("untitled_question")}
70	            </span>
71	          )}
72	        </span>
73	        {activeId === item.question.id && (
74	          <span className="absolute right-0 top-1/2 h-6 w-1 -translate-y-1/2 rounded-full bg-gray-900" />
75	        )}
76	      </button>
77	    );
78	  };
79	
80	  return (
81	    <nav aria-label={title} className="w-full space-y-1">
82	      {title && (
83	        <h3 className="px-3 py-2 text-sm font-semibold text-gray-900">
84	          {title}
85	        </h3>
86	      )}
87	      {items.map((item, index) => {
88	        // Hidden children drop out too — a row for a question that isn't on
89	        // the page is a dead end. Numbering stays stable across hides.
90	        const children = item.children.filter(
91	          (child) => !hiddenIds?.has(child.question.id),
92	        );
93	        return (
94	          <Fragment key={item.question.id}>
95	            {row(item, false)}
96	            {children.length > 0 && (
97	              <div className="ml-3 border-l border-gray-200 pl-1">
98	                {children.map((child) => row(child, true))}
99	              </div>
100	            )}
101	            {index < items.length - 1 && (
102	              <div className="relative my-1 border-t border-gray-100">
103	                {renderSeparator?.(index)}
104	              </div>
105	            )}
106	          </Fragment>
107	        );
108	      })}
109	      {footer}
110	    </nav>
111	  );
112	}
