33	 *  the AnswerOptionsEditor (default among the unit choices); the rest get
34	 *  the plain unit row below — the unit shows next to the question label in
35	 *  fill mode (`({code})`, legacy QuestionLabel behavior). */
36	const UNIT_ROW_TYPES: Question["type"][] = ["integer", "decimal", "choice"];
