65	    // that never offers Repeats also clears a previously-set flag, so it
66	    // can't linger invisibly once the chip disappears.
67	    const nextType = patch.type ?? question.type;
68	    if (question.repeats && NON_REPEATABLE_TYPES.includes(nextType)) {
69	      patch = { ...patch, repeats: false };
70	    }
71	    onChange(patch);
72	  };
