import type { RendererSubject } from "@/components/QuestionnaireV2/renderer/types";

/**
 * The full renderer's modes. `preview` is interactive without persistence
 * (builder canvas, detail preview); `readonly` renders recorded/disabled
 * fields; `fill` is the future real-submission mode — the validation seam
 * (`validation.ts`) and the structured slot's id/slug pass-through activate
 * there, while the encounter host and batch submission land in a follow-up.
 */
export type FormMode = "preview" | "readonly" | "fill";

export type { RendererSubject };

import { Provider as JotaiProvider, createStore } from "jotai";
import { createContext, useContext, useEffect, useRef, useState } from "react";

import {
  initializeResponses,
  questionnaireAtom,
  responsesAtom,
} from "@/components/QuestionnaireV2/renderer/store";

import type { QuestionnaireResponse } from "@/types/questionnaire/form";
import type { Question } from "@/types/questionnaire/question";
import type { QuestionnaireRead } from "@/types/questionnaire/questionnaire";

import type { FormMode, RendererSubject } from "./types";

interface FormContextValue {
  mode: FormMode;
  subject: RendererSubject;
  questionnaire: QuestionnaireRead;
  /** Render enable_when-hidden questions anyway (builder edit canvas). */
  revealHidden: boolean;
  /** Render inputs visually but non-interactive and out of the a11y tree
   *  (builder edit canvas — clicks land on the selection chrome instead). */
  inert: boolean;
}

const FormContext = createContext<FormContextValue | null>(null);

export function useFormRenderer(): FormContextValue {
  const context = useContext(FormContext);
  if (!context) {
    throw new Error(
      "useFormRenderer must be used inside QuestionnaireFormProvider",
    );
  }
  return context;
}

/** `id → "type:structured_type"` for every non-group question — the key that
 *  decides whether an in-progress answer survives a live tree update. */
function questionSignatures(questions: Question[]): Map<string, string> {
  const signatures = new Map<string, string>();
  const walk = (list: Question[]) => {
    for (const question of list) {
      if (question.type === "group") {
        walk(question.questions ?? []);
        continue;
      }
      signatures.set(
        question.id,
        `${question.type}:${question.structured_type ?? ""}`,
      );
    }
  };
  walk(questions);
  return signatures;
}

/**
 * Live-update merge — the difference from the old renderer's wholesale
 * re-seed (which wiped every in-progress answer whenever the questionnaire
 * identity changed). Entries survive when the question id still exists with
 * the same type/structured_type; added questions get fresh seeded entries
 * (`initial_selected` options); removed questions drop; a type change
 * re-seeds that one entry so a stale value of another shape can't linger in
 * enable_when evaluation.
 */
export function syncResponses(
  previous: Record<string, QuestionnaireResponse>,
  previousSignatures: Map<string, string>,
  questions: Question[],
): Record<string, QuestionnaireResponse> {
  const fresh = initializeResponses(questions);
  const nextSignatures = questionSignatures(questions);
  const merged: Record<string, QuestionnaireResponse> = {};
  for (const [id, seeded] of Object.entries(fresh)) {
    const existing = previous[id];
    merged[id] =
      existing && previousSignatures.get(id) === nextSignatures.get(id)
        ? { ...existing, link_id: seeded.link_id }
        : seeded;
  }
  return merged;
}

interface ProviderProps {
  questionnaire: QuestionnaireRead;
  mode: FormMode;
  subject?: RendererSubject;
  revealHidden?: boolean;
  inert?: boolean;
  children: React.ReactNode;
}

export function QuestionnaireFormProvider({
  questionnaire,
  mode,
  subject = {},
  revealHidden = false,
  inert = false,
  children,
}: ProviderProps) {
  // useState (not useMemo) so the store is created exactly once per instance
  // and never observed unseeded (same rationale as the old provider).
  const [store] = useState(() => {
    const seeded = createStore();
    seeded.set(questionnaireAtom, questionnaire);
    seeded.set(responsesAtom, initializeResponses(questionnaire.questions));
    return seeded;
  });

  // Live sync: every questionnaire identity change re-points the atom and
  // merges responses instead of wiping them — this is what lets the builder
  // feed a fresh draft object per keystroke while preview answers persist.
  const previousRef = useRef(questionnaire);
  useEffect(() => {
    if (previousRef.current === questionnaire) return;
    const previousSignatures = questionSignatures(
      previousRef.current.questions,
    );
    previousRef.current = questionnaire;
    store.set(questionnaireAtom, questionnaire);
    store.set(
      responsesAtom,
      syncResponses(
        store.get(responsesAtom),
        previousSignatures,
        questionnaire.questions,
      ),
    );
  }, [questionnaire, store]);

  return (
    <FormContext.Provider
      value={{ mode, subject, questionnaire, revealHidden, inert }}
    >
      <JotaiProvider store={store}>{children}</JotaiProvider>
    </FormContext.Provider>
  );
}

import { ComponentType, ReactNode, createContext, useContext } from "react";

import type { Question } from "@/types/questionnaire/question";

/**
 * The decoration seam: a host (the studio's edit canvas) wraps every
 * rendered question block with its own chrome — selection ring, floating
 * toolbar, click-to-select — without the renderer knowing the builder
 * exists. Preview/readonly/fill hosts provide no chrome and the renderer
 * output is exactly the plain form.
 */
export interface QuestionShellProps {
  question: Question;
  parentId: string | null;
  /** Position within the sibling list — drives move up/down affordances. */
  index: number;
  siblingCount: number;
  depth: number;
  number?: string;
  /** enable_when currently evaluates false (rendered only under
   *  `revealHidden`) — chrome shows a "hidden by conditions" cue. */
  hiddenByLogic: boolean;
  children: ReactNode;
}

export interface FormChrome {
  /** Wraps each question block. Return `children` untouched to opt out at
   *  a given depth. */
  QuestionShell?: ComponentType<QuestionShellProps>;
  /** Rendered after the children of a group (`parentId` = group id) and
   *  after the top-level list (`parentId` = null) — the "add question
   *  here" affordance. */
  AppendZone?: ComponentType<{ parentId: string | null }>;
}

const ChromeContext = createContext<FormChrome>({});

export function useFormChrome(): FormChrome {
  return useContext(ChromeContext);
}

export function FormChromeProvider({
  chrome,
  children,
}: {
  chrome: FormChrome;
  children: ReactNode;
}) {
  return (
    <ChromeContext.Provider value={chrome}>{children}</ChromeContext.Provider>
  );
}

import { NotebookPen } from "lucide-react";
import { useTranslation } from "react-i18next";

import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { Textarea } from "@/components/ui/textarea";

import { useQuestionResponse } from "@/components/QuestionnaireV2/renderer/store";

import { useFormRenderer } from "./FormContext";

/** Per-question note popover — same variants and semantics as the old
 *  renderer's NoteAffordance, re-hosted on the form context. */
export function NoteControl({
  questionId,
  variant = "merged",
}: {
  questionId: string;
  /**
   * "merged": shares the input's bordered frame, separated by a full-height
   * left rule. "standalone" (chip rows): free-standing rounded button pushed
   * to the far right behind a short vertical rule.
   */
  variant?: "merged" | "standalone";
}) {
  const { t } = useTranslation();
  const { mode } = useFormRenderer();
  const [response, updateResponse] = useQuestionResponse(questionId);

  if (!response) return null;
  if (mode === "readonly" && !response.note) return null;

  const noteDot = response.note && (
    <span className="absolute bottom-2 right-2 size-1.5 rounded-full bg-amber-500" />
  );

  return (
    <Popover>
      {variant === "standalone" ? (
        <div className="ml-auto flex shrink-0 items-center gap-2 self-center">
          <span aria-hidden className="h-6 w-px bg-gray-200" />
          <PopoverTrigger asChild>
            <button
              type="button"
              aria-label={t("add_note")}
              className="relative flex size-10 items-center justify-center rounded-md text-gray-400 hover:bg-gray-100 hover:text-gray-600"
            >
              <NotebookPen className="size-4" />
              {noteDot}
            </button>
          </PopoverTrigger>
        </div>
      ) : (
        <PopoverTrigger asChild>
          <button
            type="button"
            aria-label={t("add_note")}
            className="relative flex h-10 w-10 shrink-0 items-center justify-center border-l border-gray-200 text-gray-400 hover:text-gray-600"
          >
            <NotebookPen className="size-4" />
            {noteDot}
          </button>
        </PopoverTrigger>
      )}
      <PopoverContent align="end" className="w-72">
        <Textarea
          value={response.note ?? ""}
          readOnly={mode === "readonly"}
          placeholder={t("add_note")}
          onChange={(e) => updateResponse({ note: e.target.value })}
        />
      </PopoverContent>
    </Popover>
  );
}

import { useCallback } from "react";
import { useTranslation } from "react-i18next";

import {
  useQuestionErrors,
  useQuestionResponse,
} from "@/components/QuestionnaireV2/renderer/store";
import { STRUCTURED_REGISTRY } from "@/components/QuestionnaireV2/renderer/structured/registry";

import type { ResponseValue } from "@/types/questionnaire/form";
import type { Question } from "@/types/questionnaire/question";

import { useFormRenderer } from "./FormContext";

/**
 * Structured questions reuse the legacy QuestionTypes UI through
 * STRUCTURED_REGISTRY (the module's one sanctioned `any`). Differences from
 * the old slot, both fill-path fixes:
 * - `updateQuestionnaireResponseCB` is memoized — ChargeItemQuestion lists
 *   it in an effect dependency array, so a fresh inline arrow per render is
 *   a real loop hazard.
 * - fill mode passes `questionnaireId`/`questionnaireSlug` so
 *   MedicationRequest/ServiceRequest response-template sheets work; preview
 *   deliberately withholds them, keeping template CRUD (real POSTs) off the
 *   builder surface.
 */
export function StructuredSlot({
  question,
  disabled,
}: {
  question: Question;
  disabled: boolean;
}) {
  const { t } = useTranslation();
  const { mode, subject, questionnaire } = useFormRenderer();
  const [response, updateResponse] = useQuestionResponse(question.id);
  const errors = useQuestionErrors(question.id);

  const handleUpdate = useCallback(
    (values: ResponseValue[], _questionId: string, note?: string) =>
      updateResponse({ values, note }),
    [updateResponse],
  );

  const entry = question.structured_type
    ? STRUCTURED_REGISTRY[question.structured_type]
    : undefined;
  if (!entry || !response) return null;

  const missing = entry.requires.filter((key) => !subject[key]);
  if (missing.length > 0) {
    return (
      <div className="rounded-lg border border-dashed border-gray-300 bg-gray-50 p-4 text-sm text-gray-500">
        <p className="font-medium text-gray-700">
          {t(`structured_type__${question.structured_type}`)}
        </p>
        <p>
          {t("structured_question_requires_context", {
            contexts: missing.map((key) => t(`context__${key}`)).join(", "),
          })}
        </p>
      </div>
    );
  }

  const Component = entry.component;
  return (
    <Component
      question={question}
      questionnaireResponse={response}
      updateQuestionnaireResponseCB={handleUpdate}
      disabled={disabled}
      errors={errors}
      clearError={() => {}}
      index={0}
      withLabel={false}
      patientId={subject.patientId}
      encounterId={subject.encounterId}
      facilityId={subject.facilityId}
      {...(mode === "fill"
        ? {
            questionnaireId: questionnaire.id,
            questionnaireSlug: questionnaire.slug,
          }
        : {})}
    />
  );
}

