  onSave: () => void;
  onDiscard: () => void;
  backPath: string;
}

/** The studio header strip: back, identity, save-blocking issues, the
 *  Edit/Preview toggle and the Discard / Save Changes actions. */
export function StudioTopBar({
  questionnaire,
  questions,
  view,
  onViewChange,
  issues,
  onSelectIssue,
  dirty,
  isSaving,
  canWrite,
  onSave,
  onDiscard,
  backPath,
}: StudioTopBarProps) {
  const { t } = useTranslation();
  const [issuesOpen, setIssuesOpen] = useState(false);

  return (
    <div className="flex flex-wrap items-center gap-3 border-b border-gray-200 bg-white px-1 py-3">
      <Button
        type="button"
        variant="outline"
        size="xs"
        onClick={() => navigate(backPath)}
      >
        <ArrowLeft className="size-4" />
        {t("back")}
      </Button>

      <span aria-hidden className="hidden h-5 w-px bg-gray-200 sm:block" />

      <div className="flex min-w-0 items-center gap-2">
        <h1 className="min-w-0 truncate text-sm font-semibold text-gray-900">
          {questionnaire.title}
        </h1>
        <Badge variant="secondary" className="shrink-0 font-mono">
          {formatRevision(questionnaire.internal_revision)}
        </Badge>
        <Badge
          variant={QUESTIONNAIRE_STATUS_COLORS[questionnaire.status]}
          className="shrink-0"
        >
          {t(questionnaire.status)}
        </Badge>
      </div>

      <div className="ml-auto flex flex-wrap items-center gap-3">
        {issues.length === 0 ? (
          <span className="hidden items-center gap-1.5 text-xs text-gray-400 lg:flex">
            <CircleCheck className="size-3.5" />
            {t("ready_to_save")}
          </span>
        ) : (
          <Popover open={issuesOpen} onOpenChange={setIssuesOpen}>
            <PopoverTrigger asChild>
              <Button type="button" variant="warning" size="sm">
                <TriangleAlert className="size-4" />
                {t("issues_to_fix", { count: issues.length })}
              </Button>
            </PopoverTrigger>
            <PopoverContent align="end" className="w-80 p-1.5">
              <p className="px-2.5 pb-1 pt-2 text-[11px] font-bold uppercase tracking-wide text-gray-400">
                {t("before_you_save")}
              </p>
              <div className="max-h-72 overflow-y-auto">
                {issues.map(({ question, messageKey }) => (
                  <button
                    key={question.id}
                    type="button"
                    onClick={() => {
                      setIssuesOpen(false);
                      onSelectIssue(question.id);
                    }}
                    className="flex w-full items-start gap-2 rounded-md px-2.5 py-2 text-left hover:bg-gray-50"
                  >
                    <TriangleAlert
                      aria-hidden
                      className="mt-0.5 size-3.5 shrink-0 text-amber-600"
                    />
                    <span className="min-w-0">
                      <span className="block text-sm font-medium text-gray-900">
                        {t(messageKey)}
                      </span>
                      <span className="block truncate text-xs text-gray-500">
                        {findQuestionNumber(questions, question.id)}{" "}
                        {question.text || t("untitled_question")}
                      </span>
                    </span>
                  </button>
                ))}
              </div>
            </PopoverContent>
          </Popover>
        )}

        <EditPreviewToggle view={view} onChange={onViewChange} />

        {canWrite && (
          <>
            <Button
              type="button"
              variant="outline"
              onClick={onDiscard}
              disabled={!dirty || isSaving}
            >
              {t("discard")}
            </Button>
            <Button
              type="button"
              onClick={onSave}
              disabled={!dirty || isSaving}
            >
              <Check className="size-4" />
              {t("save_changes")}
            </Button>
          </>
        )}
      </div>
    </div>
  );
}

import { Copy, Download } from "lucide-react";
import { useState } from "react";
import { UseFormReturn } from "react-hook-form";
import { useTranslation } from "react-i18next";

import { Form } from "@/components/ui/form";

import { CloneQuestionnaireDialog } from "@/components/QuestionnaireV2/manage/CloneQuestionnaireDialog";
import { BasicInformationCard } from "@/components/QuestionnaireV2/manage/BasicInformationCard";
import { FormPropertiesSidebar } from "@/components/QuestionnaireV2/manage/FormPropertiesSidebar";
import { OrganizationsField } from "@/components/QuestionnaireV2/manage/OrganizationsField";
import { DetailFormValues } from "@/components/QuestionnaireV2/manage/questionnaireFormSchema";
import { downloadQuestionnaireJson } from "@/components/QuestionnaireV2/shared/downloadQuestionnaireJson";
import { LabeledActionButton } from "@/components/QuestionnaireV2/shared/LabeledActionButton";

import {
  QuestionnaireRead,
  QuestionnaireScope,
} from "@/types/questionnaire/questionnaire";

export interface FormSettingsPanelProps {
  scope: QuestionnaireScope;
  questionnaire: QuestionnaireRead;
  /** The studio page's metadata form — saved together with the question
   *  tree by the page's Save Changes (one full-body PUT). */
  form: UseFormReturn<DetailFormValues>;
  canWrite: boolean;
}

/**
 * The inspector's questionnaire-level state (the reference design's "Form
 * settings"): identity fields, status, subject type, organizations, clone
 * and JSON export — composed from the manage components so the detail page
 * and the studio cannot drift. Note organizations keep their own
 * immediate-save semantics (same as the detail page), independent of the
 * Save Changes flow.
 */
export function FormSettingsPanel({
  scope,
  questionnaire,
  form,
  canWrite,
}: FormSettingsPanelProps) {
  const { t } = useTranslation();
  const [cloneOpen, setCloneOpen] = useState(false);

  return (
    <div className="space-y-4">
      <div>
        <h2 className="text-sm font-semibold text-gray-900">
          {t("form_settings")}
        </h2>
        <p className="text-xs text-gray-500">{t("form_settings_hint")}</p>
      </div>

      <Form {...form}>
        <BasicInformationCard form={form} canWrite={canWrite}>
          <OrganizationsField
            scope={scope}
            questionnaireId={questionnaire.id}
            canWrite={canWrite}
          />
        </BasicInformationCard>

        <FormPropertiesSidebar
          questionnaire={questionnaire}
          form={form}
          canWrite={canWrite}
        >
          {canWrite && (
            <LabeledActionButton
              label={t("create_copy_of_form")}
              onClick={() => setCloneOpen(true)}
            >
              <Copy className="size-4" />
              {t("clone_form")}
            </LabeledActionButton>
          )}
          <LabeledActionButton
            label={t("download_the_form")}
            onClick={() => downloadQuestionnaireJson(questionnaire)}
          >
            <Download className="size-4" />
            {t("download_json")}
          </LabeledActionButton>
        </FormPropertiesSidebar>
      </Form>

      <CloneQuestionnaireDialog
        scope={scope}
        questionnaire={questionnaire}
        open={cloneOpen}
        onOpenChange={setCloneOpen}
      />
    </div>
  );
}

