export const meta = {
  name: 'studio-adversarial-review',
  description: 'Review the new questionnaire studio + form renderer commits, verify findings adversarially',
  phases: [{ title: 'Review', detail: 'four dimension reviewers' }, { title: 'Verify', detail: 'refute each finding' }],
}

const FINDINGS = {
  type: 'object',
  properties: {
    findings: { type: 'array', items: { type: 'object', properties: {
      file: { type: 'string' }, line: { type: 'number' },
      title: { type: 'string' },
      detail: { type: 'string', description: 'What is wrong and the concrete failure scenario (inputs/state -> wrong behavior)' },
      severity: { type: 'string', enum: ['critical', 'major', 'minor'] },
    }, required: ['file', 'title', 'detail', 'severity'] } },
  },
  required: ['findings'],
}

const VERDICT = {
  type: 'object',
  properties: {
    isReal: { type: 'boolean', description: 'true only if the failure scenario actually occurs in this codebase' },
    reasoning: { type: 'string' },
  },
  required: ['isReal', 'reasoning'],
}

const CONTEXT = `The repo is /Users/bodhishthomas/code/care_fe, branch bodhi/questionnaire-wysiwyg-builder. The last 3 commits (git log -3) added: (1) builder model groundwork (builderReducer duplicateQuestion/template, saveValidation findInvalidQuestions, shared/downloadQuestionnaireJson), (2) src/components/QuestionnaireV2/form/ (full renderer: FormContext live-sync provider, chrome seam, FormCanvas/QuestionBlock/SectionCard, StructuredSlot, NoteControl, validation), (3) src/components/QuestionnaireV2/studio/ (QuestionnaireStudioPage, StudioTopBar, StudioOutline, StudioCanvas, FormSettingsPanel, outlineSearch) + route repoints + en.json keys + README. Read the diff with: git show --stat HEAD~3..HEAD, then read the changed/new files fully, plus any file they import that you need to check a contract against (especially src/components/QuestionnaireV2/renderer/store.ts, renderer/inputs/*, builder/QuestionEditorCard.tsx, manage/useUpdateQuestionnaire.ts, shared/questionTree.ts).`

phase('Review')
const DIMENSIONS = [
  { key: 'state', prompt: `${CONTEXT}\n\nDimension: STATE CORRECTNESS. Hunt for real bugs in: FormContext.tsx live-sync (syncResponses merge semantics — type changes, added/removed questions, initial_selected seeding, link_id updates, the previousRef timing), the studio page's dirty tracking across reducer + react-hook-form (save, discard, refetch guard, keepDirtyValues, form.reset paths), useUpdateQuestionnaire onSaved closure staleness, duplicateQuestion reducer action (cloneSubtree link_id remapping, enable_when internal/external split, insertion), findInvalidQuestions ordering vs the old findFirstInvalidQuestion contract. Only report defects with a concrete failure scenario.` },
  { key: 'render', prompt: `${CONTEXT}\n\nDimension: RENDERER SEMANTICS. Compare form/QuestionBlock.tsx + SectionCard.tsx + FormCanvas.tsx against the old renderer/QuestionField.tsx + QuestionGroupCard.tsx + QuestionnaireRenderer.tsx line by line for behavior drift that matters: enable_when gating (hidden vs protected vs revealHidden), disabled threading (readonly/read_only/fieldset), repeats machinery (withEntryAt, entryCount, add/remove), chip-input detection, inputId/labelId contracts, styling_metadata sanitization (classes vs containerClasses on leaf vs group), structured slot prop bag vs the old StructuredQuestionSlot, NoteControl vs NoteAffordance, display-type rendering, empty/all-hidden states. The NEW module is allowed to differ in layout but not in response/visibility semantics. Only report defects with a concrete failure scenario.` },
  { key: 'ui', prompt: `${CONTEXT}\n\nDimension: STUDIO UI LOGIC. Hunt for real bugs in: StudioCanvas chrome (selection, stopPropagation, toolbar enable/disable at boundaries, depth>=2 opt-out, data-qid scroll, inert interplay — clicks on inert content reaching the wrapper), StudioOutline (searchHiddenIds correctness incl. group/children cases, preview hiddenIds union, noMatches computation, separator indices after filtering — do '+' separators insert at the right index when rows are hidden?), StudioTopBar (issues popover selection, formatRevision usage), QuestionnaireStudioPage (inspectorTarget transitions, formSelected fallback, mobile select, view init from ?mode, import param strip, empty-state paths, deleting the selected question, scrollRequest lifecycle). Only report defects with a concrete failure scenario.` },
  { key: 'conventions', prompt: `${CONTEXT}\n\nDimension: CONVENTIONS AND INTEGRATION. Check: every t() key used in the new files exists in public/locale/en.json (list any missing — grep each new key), i18n plural keys (issues_to_fix, n_questions) resolve, imports respect the module boundaries documented in src/components/QuestionnaireV2/README.md, no dead bg-primary-50 class usage in new code, type safety (no unchecked casts), the routes still register in the required raviger order, ui/ primitives not modified, form/ does not import renderer SHELL files (QuestionField, QuestionGroupCard, RendererContext, TopLevelCard, RendererFooter, NoteAffordance, StructuredQuestionSlot, QuestionnaireRenderer) — engine files only, and the old builder page still compiles unmounted. Only report defects with a concrete failure scenario.` },
]

const results = await pipeline(
  DIMENSIONS,
  d => agent(d.prompt + '\n\nReturn findings via StructuredOutput. You are read-only.', { label: 'review:' + d.key, phase: 'Review', schema: FINDINGS, agentType: 'Explore' }),
  (review, d) => parallel((review?.findings ?? []).map(f => () =>
    agent(`${CONTEXT}\n\nAdversarially verify this code-review finding. Try hard to REFUTE it by reading the actual code paths; default to isReal=false unless the failure scenario concretely occurs.\n\nFinding (${f.severity}) in ${f.file}${f.line ? ':' + f.line : ''}: ${f.title}\n${f.detail}`, { label: 'verify:' + (f.title || '').slice(0, 40), phase: 'Verify', schema: VERDICT, agentType: 'Explore' })
      .then(v => ({ ...f, dimension: d.key, verdict: v }))
  ))
)

const confirmed = results.flat().filter(Boolean).filter(f => f.verdict?.isReal)
const refuted = results.flat().filter(Boolean).filter(f => f.verdict && !f.verdict.isReal).map(f => f.title)
return { confirmed, refutedTitles: refuted }

